150	function persistTrace(trace: StoredOverlayTrace): void {
151	  if (!settings.recordingWhilePlaying) return;
152	  try {
153	    localStorage.setItem(`${TRACE_KEY_PREFIX}${trace.gameId}`, JSON.stringify(trace));
154	  } catch {
155	    // Recording must never interrupt gameplay.
156	  }
157	}
