729	/** Refill the ticket list and the approve/deny section from the live view — never the message box, so an in-progress draft survives a tick. */
730	function refreshInterventionPanel(activeGame: PlayableGame): void {
731	  if (activeGame.name !== "restaurant-arena") return;
732	  const els = interveneEls();
733	  if (!els.panel) return;
734	  const view = arenaView(activeGame);
735	
736	  const live = (view.orders ?? []).filter((order) => order.status !== "served" && order.status !== "cancelled");
737	  if (els.tickets) {
738	    els.tickets.innerHTML = live.length
739	      ? live
740	          .map((order) => {
741	            const label = (order.tableId ?? order.id).replace("table-", "T");
742	            const alreadyHigh = order.priority === "high";
743	            return `<button type="button" class="arena-intervene-ticket" data-order-id="${order.id}"${alreadyHigh ? " data-already-high" : ""}>${label} · ${order.items.join("+") || "—"}${alreadyHigh ? " (high)" : ""}</button>`;
744	          })
745	          .join("")
746	      : `<span class="arena-intervene-empty">No live tickets.</span>`;
747	  }
748	
749	  // The round budget (#262). The engine owns it; the panel only reports it,
750	  // so the human manager and the model manager cannot drift apart.
751	  const withRounds = activeGame as PlayableGame & { roundStatus?: () => RoundStatus };
752	  const round = withRounds.roundStatus?.();
753	  if (round && els.budget) {
754	    els.budget.textContent = round.canAct
755	      ? `Round ${round.round} of ${round.totalRounds} — 1 action left`
756	      : `Round ${round.round} of ${round.totalRounds} — spent, the floor runs itself now`;
757	    els.budget.dataset.spent = String(!round.canAct);
758	  }
759	  if (round) {
760	    // A spent round closes every write control at once. The keyboard hits the
761	    // same budget inside the engine, so there is no shortcut around this.
762	    for (const control of [els.send, els.correct, els.pass]) {
763	      if (control) control.disabled = !round.canAct;
764	    }
765	    if (els.text) els.text.disabled = !round.canAct;
766	    els.tickets?.querySelectorAll("button").forEach((button) => {
767	      (button as HTMLButtonElement).disabled = !round.canAct;
768	    });
769	  }
770	
771	  if (els.approve) {
772	    const decision = view.decision;
773	    if (decision) {
774	      els.approve.hidden = false;
775	      els.approve.innerHTML =
776	        `<p class="arena-intervene-label">${decision.speaker} needs a call — ${decision.title}</p>` +
777	        decision.options
778	          .map(
779	            (option) =>
780	              `<button type="button" class="arena-intervene-approve-option" data-tone="${option.tone}" data-decision-id="${decision.id}" data-option-id="${option.id}" data-speaker-role="${decision.speakerRole}">${option.label}</button>`,
781	          )
782	          .join("");
783	    } else {
784	      els.approve.hidden = true;
785	      els.approve.innerHTML = "";
786	    }
787	  }
788	}
