results.content:
.return-prompt {
        position: fixed;
        inset: 0;
        z-index: 10;
        display: grid;
        place-items: center;
        padding: 28px;
        background: rgba(15, 23, 42, 0.28);
        backdrop-filter: blur(6px);
      }
      .return-prompt[hidden] { display: none; }
      .return-card {
        width: min(100%, 340px);
        padding: 26px 24px 22px;
        border: 1px solid var(--line);
        border-radius: var(--radius-l);
        background: var(--bg-1);
        text-align: center;
        box-shadow: var(--shadow-window);
      }
      .return-card h2 {
        margin: 0 0 20px;
        font-size: 22px;
        font-weight: 700;
        letter-spacing: -.02em;
      }
      .return-prompt[data-tone="win"] .return-card h2 { color: var(--gold); }
      .return-prompt[data-tone="loss"] .return-card h2 { color: var(--danger); }
      .return-prompt[data-tone="draw"] .return-card h2 { color: var(--blue); }
      .return-actions { display: grid; gap: 8px; }
      .return-actions button {
        min-height: 42px;
        border: 1px solid var(--line);
        border-radius: var(--radius-m);
        background: var(--bg-3);
        color: var(--ink);
        cursor: pointer;
        font-size: 14px;
        box-shadow: var(--shadow-sm);
        transition: border-color .12s ease, background .12s ease, box-shadow .12s ease;
      }
      .return-actions button:hover, .return-actions button:focus-visible {
        border-color: var(--hover);
        outline: none;
      }
      .return-actions .primary {
        background: var(--accent);
        border-color: var(--accent);
        color: var(--accent-ink);
        font-weight: 700;
      }
      .return-actions .primary:hover, .return-actions .primary:focus-visible { background: var(--banana-deep); }
      .how-to-play-card {
        width: min(100%, 440px);
        max-height: min(92vh, 640px);
        text-align: left;
        display: flex;
        flex-direction: column;
        overflow: hidden;
      }
      .how-to-play-card h2 { text-align: center; }
      .how-to-play-body {
        overflow-y: auto;
        display: grid;
        gap: 12px;
        margin-bottom: 16px;
        font-size: 13px;
        line-height: 1.45;
        color: var(--ink);
      }
      .how-to-play-body h3 {
        margin: 0 0 4px;
        font-size: 11px;
        letter-spacing: .05em;
        text-transform: uppercase;
        color: var(--crayola-blue);
      }
      .how-to-play-body p, .how-to-play-body ul { margin: 0; color: var(--muted); }
      .how-to-play-body ul { padding-left: 1.15em; }
      .how-to-play-body li + li { margin-top: 4px; }
      kbd {
        display: inline-block;
        min-width: 20px;
        padding: 1px 5px;
        border: 1px solid currentColor;
        border-radius: 4px;
        font: 600 11px/1.5 var(--mono);
        opacity: .85;
      }

      /* ── Board game-over overlay ─────────────────────────────── */
      .game-end-overlay {
        position: absolute;
        inset: 0;
        z-index: 5;
        display: grid;
        place-items: center;
        padding: 16px;
        background: rgba(6, 10, 14, 0.82);
        backdrop-filter: blur(4px);
        border-radius: inherit;
        animation: fade-in 0.25s ease-out;
      }
      @keyframes fade-in {
        from { opacity: 0; }
        to { opacity: 1; }
      }
      .game-end-content {
        width: 100%;
        max-width: 300px;
        text-align: center;
      }
      .game-end-title {
        margin: 0 0 10px;
        font-size: 24px;
        font-weight: 800;
        letter-spacing: -.02em;
        color: #f8fafc;
        text-shadow: 0 1px 3px rgba(0, 0, 0, .4);
      }
      .game-end-overlay[data-tone="win"] .game-end-title { color: var(--gold); }
      .game-end-overlay[data-tone="loss"] .game-end-title { color: var(--danger); }
      .game-end-overlay[data-tone="draw"] .game-end-title { color: var(--blue); }

      .game-end-stats {
        margin: 0 auto 20px;
        max-width: 240px;
        padding-top: 12px;
        border-top: 1px solid rgba(255, 255, 255, .14);
        font-size: 13.5px;
        font-weight: 500;
        color: rgba(255, 255, 255, .78);
        line-height: 1.55;
        letter-spacing: .01em;
      }
      /* Service report on the end-of-shift card: the local grade, the six
