1	import { invoke } from "./tauri-bridge.js";
2	
3	export interface UpdateAvailable {
4	  fromVersion: string;
5	  toVersion: string;
6	}
7	
8	/** Mirrors `UpdatePlan` in tauri/src/main.rs (from ~/.gamepigeon/install-context.json). */
9	export interface UpdatePlan {
10	  canSelfUpdate: boolean;
11	  manualCommand: string;
12	  method: string;
13	  harness: string;
14	}
15	
16	/**
17	 * Used when the backend cannot answer (browser preview, or a command that is
18	 * missing on an older binary). Attempting the update is the safer default there:
19	 * the old Claude-only path still runs, and a failure reports itself in-line
20	 * along with the command to run by hand.
21	 */
22	const FALLBACK_PLAN: UpdatePlan = {
23	  canSelfUpdate: true,
24	  manualCommand: "npx -y bun x @tui-games/tui@latest install",
25	  method: "unknown",
26	  harness: "unknown",
27	};
28	
29	export type UpdateLoadingElements = {
30	  loading: HTMLElement;
31	  version: HTMLElement;
32	  note: HTMLElement;
33	  manual: HTMLElement | null;
34	  command: HTMLElement | null;
35	  copy: HTMLButtonElement | null;
36	};
37	
38	function loadingElements(): UpdateLoadingElements | null {
39	  const loading = document.querySelector<HTMLElement>("#update-loading");
40	  const version = document.querySelector<HTMLElement>("#update-loading-version");
41	  const note = document.querySelector<HTMLElement>("#update-loading-note");
42	  if (!loading || !version) return null;
43	  return {
44	    loading,
45	    version,
46	    note: note ?? version,
47	    manual: document.querySelector<HTMLElement>("#update-manual"),
48	    command: document.querySelector<HTMLElement>("#update-command"),
49	    copy: document.querySelector<HTMLButtonElement>("#update-copy-command"),
50	  };
51	}
52	
53	let isAutoUpdating = false;
54	
55	export function setUpdateLoading(visible: boolean, version = "", noteText = ""): void {
56	  const elements = loadingElements();
57	  if (!elements) return;
58	  elements.version.textContent = version ? `Installing v${version}…` : "Updating Tui…";
59	  if (noteText) {
60	    elements.note.textContent = noteText;
61	  } else {
62	    elements.note.textContent = "Keep Tui open — your game will restart automatically when finished.";
63	  }
64	  // Each new state starts without a command; only a plan that needs one shows it.
65	  if (elements.manual) elements.manual.hidden = true;
66	  elements.loading.hidden = !visible;
67	  document.querySelector<HTMLElement>(".app")?.setAttribute("aria-busy", String(visible));
68	}
69	
70	/**
71	 * Only a Claude marketplace install, a copied adapter, or a global npm install
72	 * can be upgraded from in here. Everything else (a dev checkout, an install we
73	 * cannot identify) gets the command to run instead of an automatic attempt that
74	 * would only ever fail — the "Tui plugin install path not found." dead end of
75	 * issue #176.
76	 */
77	export function applyUpdatePlan(
78	  elements: UpdateLoadingElements,
79	  plan: UpdatePlan,
80	  options: { alsoShowCommand?: boolean } = {},
81	): void {
82	  elements.loading.dataset.method = plan.method;
83	  if (!elements.manual || !elements.command || !elements.copy) return;
84	  elements.manual.hidden = plan.canSelfUpdate && !options.alsoShowCommand;
85	  if (elements.manual.hidden) return;
86	  elements.command.textContent = plan.manualCommand;
87	  elements.copy.textContent = "Copy";
88	}
89	
90	async function readUpdatePlan(): Promise<UpdatePlan> {
91	  try {
92	    return (await invoke<UpdatePlan | null>("read_update_plan")) ?? FALLBACK_PLAN;
93	  } catch {
94	    return FALLBACK_PLAN;
95	  }
96	}
97	
98	export async function checkAndAutoUpdate(): Promise<void> {
99	  if (isAutoUpdating) return;
100	
101	  try {
102	    const flag = await invoke<UpdateAvailable | null>("read_update_flag");
103	    if (!flag?.fromVersion || !flag?.toVersion) return;
104	
105	    const elements = loadingElements();
106	    if (!elements) return;
107	    const plan = await readUpdatePlan();
108	
109	    // An install the overlay cannot upgrade never starts a spinner it could not
110	    // finish: it shows the version and the one command that does the job.
111	    if (!plan.canSelfUpdate) {
112	      setUpdateLoading(true, flag.toVersion, "Update from your terminal:");
113	      applyUpdatePlan(elements, plan);
114	      return;
115	    }
116	
117	    isAutoUpdating = true;
118	    setUpdateLoading(true, flag.toVersion);
119	
120	    try {
121	      const message = await invoke<string>("run_plugin_update");
122	      setUpdateLoading(true, flag.toVersion, message || "Restarting Tui…");
123	    } catch (error) {
124	      isAutoUpdating = false;
125	      const errorMsg = error instanceof Error ? error.message : String(error);
126	      setUpdateLoading(true, flag.toVersion, `Update note: ${errorMsg}`);
127	      // A failed self-update leaves the terminal command as the way out, so the
128	      // screen stays up rather than timing out on a dead end.
129	      applyUpdatePlan(elements, plan, { alsoShowCommand: true });
130	    }
131	  } catch {
132	    // Flag read failed or non-Tauri environment
133	  }
134	}
135	
136	/** Legacy banner refresh alias for screen transitions, now runs auto-update check */
137	export async function refreshUpdateBanner(): Promise<void> {
138	  const params = new URLSearchParams(window.location.search);
139	  if (params.get("update") === "true") {
140	    setUpdateLoading(true, "0.2.14");
141	    return;
142	  }
143	  await checkAndAutoUpdate();
144	}
145	
146	/** Copies the command; falls back to selecting it when the webview blocks the clipboard. */
147	async function copyManualCommand(elements: UpdateLoadingElements): Promise<void> {
148	  if (!elements.command || !elements.copy) return;
149	  const copy = elements.copy;
150	  const command = elements.command.textContent ?? "";
151	  if (!command) return;
152	  try {
153	    await navigator.clipboard.writeText(command);
154	    copy.textContent = "Copied";
155	    window.setTimeout(() => {
156	      copy.textContent = "Copy";
157	    }, 2000);
158	  } catch {
159	    // Last resort: select the text so ⌘C/Ctrl+C works.
160	    const range = document.createRange();
161	    range.selectNodeContents(elements.command);
162	    const selection = window.getSelection();
163	    selection?.removeAllRanges();
164	    selection?.addRange(range);
165	    copy.textContent = "Press ⌘C";
166	  }
167	}
168	
169	/** Auto-updates run on their own; only the manual-command copy needs a handler. */
170	export function bindUpdateBanner(): void {
171	  const elements = loadingElements();
172	  if (!elements?.copy) return;
173	  elements.copy.addEventListener("click", () => {
174	    void copyManualCommand(elements);
175	  });
176	}
177

