arguments.content:
/**
 * Who is holding the run still, and what the pause card says about it.
 *
 * A run can be held by more than one thing at a time — the harness paused it
 * at a turn boundary, the player opened How to Play, the window is a pill in
 * the corner of the screen — and those holds end in any order. A single
 * boolean loses that: closing How to Play would resume a shift the agent had
 * paused, and the dinner rush would start burning down while the player is
 * back in their terminal. So every holder names itself and the run only moves
 * again once the last hold is gone.
 */
export type PauseReason = "agent" | "dialog" | "minimized";

export class PauseGate {
  private readonly holds = new Set<PauseReason>();

  /** True only when this hold is the one that stopped the run. */
  hold(reason: PauseReason): boolean {
    const wasPaused = this.isPaused();
    this.holds.add(reason);
    return !wasPaused;
  }

  /** True only when dropping this hold is what let the run move again. */
  release(reason: PauseReason): boolean {
    if (!this.holds.delete(reason)) return false;
    return !this.isPaused();
  }

  held(reason: PauseReason): boolean {
    return this.holds.has(reason);
  }

  isPaused(): boolean {
    return this.holds.size > 0;
  }

  reasons(): PauseReason[] {
    return [...this.holds];
  }

  /** Drops every hold: a fresh run always starts from a standing start. */
  clear(): boolean {
    const wasPaused = this.isPaused();
    this.holds.clear();
    return wasPaused;
  }
}

/** What the run looks like from outside the engine, for the pause card. */
export interface PausedRun {
  over: boolean;
  won: boolean;
}

export interface PausePromptState {
  title: string;
  /** Tints the card's heading; absent while the run can still be played on. */
  tone?: "win" | "loss";
  /** False when there is nothing left to go back to. */
  canContinue: boolean;
}

/**
 * The pause card is also what a player sees if the agent stops them right as a
 * shift ends, so it has to be able to say "that shift is finished" instead of
 * offering to continue a run that cannot be continued. `null` is the menu:
 * paused with no run behind it.
 */
export function pausePrompt(run: PausedRun | null): PausePromptState {
  if (!run) return { title: "Paused", canContinue: false };
  if (run.over) {
    return run.won
      ? { title: "Shift complete", tone: "win", canContinue: false }
      : { title: "Shift over", tone: "loss", canContinue: false };
  }
  return { title: "Paused", canContinue: true };
}

