/** Prefer the real Tauri LogicalSize under Tauri so setSize accepts it. */
export function overlayLogicalSize(width: number, height: number): LogicalSize | TauriLogicalSize {
  return isTauri() ? new TauriLogicalSize(width, height) : new LogicalSize(width, height);
}

export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

/** The boot frame, and what the expand control returns to. */
export const COMPACT_SIZE: OverlaySize = { width: 600, height: 850 };
export const EXPANDED_SIZE: OverlaySize = { width: 830, height: 900 };
/** Minimized: the window *is* the handheld pill, so it shrinks to fit it. */
export const PILL_SIZE: OverlaySize = { width: 144, height: 48 };
/** The floor a restored window is never taken below. */
export const MIN_SIZE: OverlaySize = { width: 500, height: 700 };

export type OverlayWindowMode = "compact" | "expanded" | "pill";

/**
 * A mode's frame, minimum included. The minimum travels with the size because
 * the pill sits far below the floor the arcade frame needs: shrinking to it
 * without lowering the minimum first leaves a 500×700 "pill", and growing back
 * out without raising the minimum again lets the next drag squash the board.
 */
export function overlayWindowSize(mode: OverlayWindowMode): { size: OverlaySize; minSize: OverlaySize } {
  if (mode === "pill") return { size: PILL_SIZE, minSize: PILL_SIZE };
  return { size: mode === "expanded" ? EXPANDED_SIZE : COMPACT_SIZE, minSize: MIN_SIZE };
}

/**
 * Resizes the real window into a mode. The cast is the reason this lives here
 * rather than in the caller: the preview's stand-in size class cannot
 * structurally satisfy Tauri's `LogicalSize` (which carries IPC serialization
 * methods), while the preview window only ever reads width/height back off it.
 */
export async function applyOverlayWindowSize(
  overlayWindow: OverlayWindow,
  mode: OverlayWindowMode,
): Promise<void> {
  const { size, minSize } = overlayWindowSize(mode);
  await overlayWindow.setMinSize(overlayLogicalSize(minSize.width, minSize.height) as TauriLogicalSize);
  await overlayWindow.setSize(overlayLogicalSize(size.width, size.height) as TauriLogicalSize);
}

