// ── Window frame ─────────────────────────────────────────────────────
//
// The overlay wears its own titlebar, so every frame change is ours to make:
// boot, the expand control, and the minimized pill all go through
// applyWindowFrame(). The sizes themselves live in tauri-bridge.ts so the
// native shell and the browser preview cannot drift apart.

function windowMode(): OverlayWindowMode {
  if (minimized) return "pill";
  return expanded ? "expanded" : "compact";
}

function applyWindowFrame(): void {
  void applyOverlayWindowSize(windowHandle, windowMode()).catch(() => {
    // A frame we could not set is not worth interrupting a shift over.
  });
}

/** The control shows where it will take you, not where you are. */
function renderResizeControl(): void {
  const control = document.querySelector<HTMLButtonElement>("#resize");
  if (!control) return;
  setText(control, expanded ? "↙" : "↗");
  control.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
}

function toggleWindowSize(): void {
  expanded = !expanded;
  renderResizeControl();
  applyWindowFrame();
}

/**
 * Collapse to the pill. The run is held while it is down there: a shift
 * ticking away behind a 144×48 pill would spend the night's clock on a floor
 * nobody is watching.
 */
function minimizeToPill(): void {
  if (minimized) return;
  closeDialog();
  minimized = true;
  document.body.dataset.mode = "pill";
  holdRun("minimized");
  persistRun();
  applyWindowFrame();
  document.querySelector<HTMLButtonElement>("#pill")?.focus();
}

function restoreFromPill(): void {
  if (!minimized) return;
  minimized = false;
  delete document.body.dataset.mode;
  applyWindowFrame();
  releaseRun("minimized");
}

/**
 * The pill is one control that has to do two things — drag the window, click
 * to reopen — with no titlebar to separate them. Tauri only hands dragging to
 * elements it owns (`data-tauri-drag-region`), and handing this one straight
 * to `startDragging()` on pointerdown swallows the click, so the drag only
 * starts once the pointer has actually travelled.
 */
function bindPill(): void {
  const pill = document.querySelector<HTMLButtonElement>("#pill");
  if (!pill) return;
  let origin: { x: number; y: number } | undefined;
  let dragged = false;

  pill.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    origin = { x: event.clientX, y: event.clientY };
    dragged = false;
  });
  pill.addEventListener("pointermove", (event) => {
    if (!origin || dragged) return;
    if (Math.abs(event.clientX - origin.x) + Math.abs(event.clientY - origin.y) < 4) return;
    dragged = true;
    void Promise.resolve(windowHandle.startDragging()).catch(() => undefined);
  });
  pill.addEventListener("pointerup", () => {
    origin = undefined;
  });
  pill.addEventListener("click", () => {
    // A click that ended a drag is the drag finishing, not a request to reopen.
    if (dragged) {
      dragged = false;
      return;
    }
    restoreFromPill();
  });
}

/** Titlebar controls: resize, minimize, and shut down for the session. */
function bindWindowChrome(): void {
  renderResizeControl();
  document.querySelector<HTMLButtonElement>("#resize")?.addEventListener("click", toggleWindowSize);
  document.querySelector<HTMLButtonElement>("#hide")?.addEventListener("click", minimizeToPill);
  document.querySelector<HTMLButtonElement>("#shutdown")?.addEventListener("click", () => {
    // The process is about to go: journal the run first so the next launch can
    // rebuild it, and hand the trace over as a client shutdown rather than a
    // completed shift — a shutdown never submits a score.
    persistRun();
    endRun("client_closed");
    void invoke("shutdown").catch(() => undefined);
  });
  bindPill();
}

function drawGate(): void {
  screen = "gate";

