//
// The overlay wears its own titlebar, so every frame change is ours to make:
// boot, the expand control, and the minimized pill all go through
// applyWindowFrame(). The sizes themselves live in tauri-bridge.ts so the
// native shell and the browser preview cannot drift apart.

function windowMode(): OverlayWindowMode {
  if (minimized) return "pill";
  return expanded ? "expanded" : "compact";
}

function applyWindowFrame(): void {
  void applyOverlayWindowSize(windowHandle, windowMode()).catch(() => {
    // A frame we could not set is not worth interrupting a shift over.
  });
}

/** The control shows where it will take you, not where you are. */
function renderResizeControl(): void {
  const control = document.querySelector<HTMLButtonElement>("#resize");
  if (!control) return;
  setText(control, expanded ? "↙" : "↗");
  control.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
}

function toggleWindowSize(): void {
  expanded = !expanded;
  renderResizeControl();
  applyWindowFrame();
}

/**
 * Collapse to the pill. The run is held while it is down there: a shift
 * ticking away behind a 144×48 pill would spend the night's clock on a floor
 * nobody is watching.
 */
