     export interface OverlaySize { readonly width: number; readonly height: number }

     /** The boot frame, and what the expand control returns to. */
     export const COMPACT_SIZE: OverlaySize = { width: 600, height: 850 };
     export const EXPANDED_SIZE: OverlaySize = { width: 830, height: 900 };
     /** Minimized: the window *is* the handheld pill, so it shrinks to fit it. */
     export const PILL_SIZE: OverlaySize = { width: 144, height: 48 };
