     export function overlayWindowSize(mode: OverlayWindowMode): { size: OverlaySize; minSize: OverlaySize } {
       if (mode === "pill") return { size: PILL_SIZE, minSize: PILL_SIZE };
       return { size: mode === "expanded" ? EXPANDED_SIZE : COMPACT_SIZE, minSize: MIN_SIZE };
