443	/**
444	 * The pill is one control that has to do two things — drag the window, click
445	 * to reopen — with no titlebar to separate them. Tauri only hands dragging to
446	 * elements it owns (`data-tauri-drag-region`), and handing this one straight
447	 * to `startDragging()` on pointerdown swallows the click, so the drag only
448	 * starts once the pointer has actually travelled.
449	 */
450	function bindPill(): void {
451	  const pill = document.querySelector<HTMLButtonElement>("#pill");
452	  if (!pill) return;
453	  let origin: { x: number; y: number } | undefined;
454	  let dragged = false;
455	
456	  pill.addEventListener("pointerdown", (event) => {
457	    if (event.button !== 0) return;
458	    origin = { x: event.clientX, y: event.clientY };
459	    dragged = false;
460	  });
461	  pill.addEventListener("pointermove", (event) => {
462	    if (!origin || dragged) return;
463	    if (Math.abs(event.clientX - origin.x) + Math.abs(event.clientY - origin.y) < 4) return;
464	    dragged = true;
465	    void Promise.resolve(windowHandle.startDragging()).catch(() => undefined);
466	  });
467	  pill.addEventListener("pointerup", () => {
468	    origin = undefined;
469	  });
470	  pill.addEventListener("click", () => {
471	    // A click that ended a drag is the drag finishing, not a request to reopen.
472	    if (dragged) {
473	      dragged = false;
474	      return;
475	    }
476	    restoreFromPill();
477	  });
478	}
