696	  return {
697	    queueMs: response.queueMs,
698	    providerMs: response.providerMs,
699	    ...(response.inputTokens !== undefined ? { inputTokens: response.inputTokens } : {}),
700	    ...(response.outputTokens !== undefined ? { outputTokens: response.outputTokens } : {}),
701	    ...(response.cachedInputTokens !== undefined ? { cachedInputTokens: response.cachedInputTokens } : {}),
