706	function attachWorkerOrchestrator(activeGame: PlayableGame): void {
707	  if (!workerModel || activeGame.name !== "restaurant-arena") return;
708	  workerActivity.length = 0;
709	  const arena = activeGame as unknown as RestaurantGame;
710	  const client = new WorkerModelClient({
711	    retries: 0,
712	    // The Rust transport bounds the provider call and starts that bound after
713	    // the request budget admits it, so queue time is not charged to the
714	    // worker. A timer here would start while the request is still in line and
715	    // abort a crew that is only waiting its turn.
716	    timeoutMs: null,
717	    complete: async (request: ModelRequest, signal: AbortSignal) => {
718	      const role = request.observation.role;
719	      const startedAt = performance.now();
720	      setWorkerStatus(role, "thinking");
721	      // A request already queued behind the account's share is not pending on
722	      // the model; the budget banner is the more specific thing to say. The
723	      // activity feed still logs the request either way -- it is a log of what
724	      // happened, not a description of the current state.
725	      if (shouldReportFallback(workerBudget)) setWorkerMode(`Pending · ${workerModelLabel()} · ${role}`, "pending");
726	      addWorkerActivity(`${role}: requested live action`);
727	      const requestId = crypto.randomUUID();
728	      const cancel = () => void invoke("cancel_worker_model", { requestId });
729	      signal.addEventListener("abort", cancel, { once: true });

results.content:
730	      try {
731	        const response = await invoke<WorkerModelResponse>("complete_worker_model", {
732	          requestId,
733	          request: { systemPrompt: request.systemPrompt, turnPrompt: request.turnPrompt },
734	        });
735	        if (signal.aborted) throw new Error("model request canceled");
736	        setWorkerStatus(role, "acting");
737	        addWorkerActivity(`${role}: response received in ${Math.round(performance.now() - startedAt)}ms`);
738	        return { text: response.text, metrics: workerModelMetrics(response) };
739	      } finally {
740	        signal.removeEventListener("abort", cancel);
741	      }
742	    },
743	  });
744	  let orchestrator: WorkerOrchestrator;
745	  orchestrator = new WorkerOrchestrator(arena, {
746	    client,
747	    model: workerModel,
748	    tickIntervalMs: () => arena.tickMs() || 1_000,
749	    onError: (turn) => {
750	      if (workerOrchestrator !== orchestrator) return;
751	      setWorkerStatus(turn.role, "error");
752	      addWorkerActivity(`${turn.role}: fallback — ${turn.error ?? "invalid action"}`);
753	      // A shift held back by the shared account is waiting, not broken (#281).
754	      // Only the banner is suppressed; the feed above still records the turn.
755	      if (!shouldReportFallback(workerBudget)) return;
756	      setWorkerMode(`Fallback · ${workerModelLabel()} · ${turn.role}: ${turn.error ?? "invalid action"}`, "error");
757	    },
758	    onTick: (report: OrchestratorTick) => {
759	      if (workerOrchestrator !== orchestrator || game !== activeGame) return;
760	      for (const turn of report.turns) {
761	        if (turn.status === "accepted") {
762	          setWorkerStatus(turn.role, "acting");
763	          addWorkerActivity(`${turn.role}: applied ${turn.action?.tool ?? "action"}`);
764	        }
765	        else if (turn.status === "fallback" || turn.status === "rejected") setWorkerStatus(turn.role, "error");
766	      }
767	      // Turns landing again is proof the account is answering, whatever the
768	      // last throttle said was left on its countdown.
769	      if (report.turns.every((turn) => turn.status === "accepted")) setWorkerBudget(WORKER_BUDGET_CLEAR);
770	      drawGame();
771	    },
772	  });
773	  workerOrchestrator = orchestrator;
774	}
