997	  // Whatever the target checks already reported is dropped here: showing
998	  // "Takings $96" twice, once as a verdict and once as a stat, made the card
999	  // longer without making it say more.
1000	  const checked = new Set((debrief.targets ?? []).map((target) => target.label.toLowerCase()));
1001	  const lines = debrief.lines
1002	    .filter((line) => !checked.has(line.label.toLowerCase()))
1003	    .map(
