1009	  // The verdict names which condition decided it. `lines` below are a
1010	  // read-at-a-glance summary of the shift on their own thresholds, which are
1011	  // not tonight's pass bar — keeping the two apart is what stops a green
1012	  // "Walkouts 2" from sitting under a MISSED verdict it actually caused.
1013	  const targets = (debrief.targets ?? [])
1014	    .map(
1015	      (target) =>
1016	        `<li class="debrief-check${target.met ? " is-met" : ""}">` +
1017	        `<span class="check-mark">${target.met ? "met" : "miss"}</span>` +
1018	        `<span class="check-label">${escapeHtml(target.label)}</span>` +
1019	        `<span class="check-value">${escapeHtml(target.value)}</span>` +
1020	        `<span class="check-req">needs ${escapeHtml(target.requirement)}</span>` +
1021	        `</li>`,
1022	    )
1023	    .join("");
1024	  return `
1025	    <div class="arena-debrief"${debrief.met ? ' data-met="yes"' : ""}>
1026	      <p class="debrief-scope">Local gameplay summary · not an official evaluation</p>
1027	      <p class="debrief-target">${debrief.met ? "LOCAL TARGET MET" : "LOCAL TARGET MISSED"}</p>
1028	      <p class="debrief-grade"><strong>${escapeHtml(debrief.grade)}</strong> ${escapeHtml(debrief.headline)}</p>
1029	      ${targets ? `<p class="debrief-criteria">Local target checks</p><ul class="debrief-checks">${targets}</ul>` : ""}
1030	      <p class="debrief-criteria">Raw operational facts</p>
1031	      <div class="debrief-stats">${lines}</div>
1032	      <p class="debrief-caveat">No wait figure: the engine derives only a whole-shift clock reading, not an arrival-to-seat measurement.</p>
