1037	/**
1038	 * The evidence receipt: what the shift actually recorded, counted off the
1039	 * run's own journal — the same events `Export Trace` writes out as
1040	 * restaurant-arena-trace/v3.
1041	 *
1042	 * Split by who authored each event, because that split is the whole point of
1043	 * the export: what the house did on its own (`system`) has to stay separable
1044	 * from what the manager handed over (`player`) and what the workers did with
1045	 * it. Every number here is counted, never estimated, and nothing is
1046	 * attributed to a model that did not stamp the event itself.
1047	 */
1048	function getArenaEvidenceHtml(): string {
1049	  if (!game || game.name !== "restaurant-arena") return "";
1050	  const journal = game as unknown as { getRecordedEvents?: () => { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[] };
1051	  if (typeof journal.getRecordedEvents !== "function") return "";
1052	  let events: { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[];
1053	  try {
1054	    events = journal.getRecordedEvents();
1055	  } catch (err) {
1056	    console.error("Failed to read the arena event journal:", err);
1057	    return "";
1058	  }
1059	  const system = events.filter((event) => event.actorId === "system").length;
1060	  const manager = events.filter((event) => event.actorId === "player").length;
1061	  const worker = events.length - system - manager;
1062	  const rejected = events.filter((event) => event.toolResult?.ok === false).length;
1063	  const modelStamped = events.filter((event) => event.model !== undefined && event.model !== null).length;
1064	  // Only the authorship split gets tiles — that split is what the export is
1065	  // for. The rest is one line, because a six-tile grid made a footnote look
1066	  // like a scoreboard.
1067	  const rows: [string, string][] = [
1068	    ["System", `${system}`],
1069	    ["Your handover", `${manager}`],
1070	    ["Worker turns", `${worker}`],
1071	  ];
1072	  return `
1073	    <div class="arena-evidence">
