import { createEventId } from "../recording/ids.js";

export const ANALYTICS_EVENT_TYPES = {
  appOpened: "app.opened",
  accountSignedUp: "account.signed_up",
  accountSignedIn: "account.signed_in",
  gameStarted: "game.started",
  gameEnded: "game.ended",
  pluginLaunched: "plugin.launched",
  pluginReattached: "plugin.reattached",
  agentTaskCompleted: "agent.task_completed",
  siteVisited: "site.visited",
  referralCreated: "referral.created",
  referralRedeemed: "referral.redeemed",
  paymentSucceeded: "payment.succeeded",
} as const;

export type AnalyticsEventType =
  (typeof ANALYTICS_EVENT_TYPES)[keyof typeof ANALYTICS_EVENT_TYPES];
export type AuthMethod = "password" | "google" | "github";

export interface AnalyticsEventDataMap {
  "app.opened": { app_version: string; platform: "tui" | "overlay" };
  "account.signed_up": { method: AuthMethod };
  "account.signed_in": { method: AuthMethod };
  "game.started": { game_type: string; variation_id: string };
  "game.ended": {
    game_type: string;
    variation_id: string;
    outcome: "completed" | "abandoned";
    score: number;
    success: boolean;
    duration_ms: number;
    actions_taken: number;
  };
  "plugin.launched": { harness: string };
  "plugin.reattached": { harness: string };
  "agent.task_completed": { harness: string };
  "site.visited": { referrer_host?: string; campaign?: string };
  "referral.created": { channel?: string };
  "referral.redeemed": { channel?: string };
  "payment.succeeded": { plan: string; currency: string; amount_minor: number };
}

export interface AnalyticsCloudEvent<T extends AnalyticsEventType = AnalyticsEventType> {
====
fn append_local_score_to(
    path: &std::path::Path,
    score: LocalScoreInput,
) -> Result<LocalScoreEntry, String> {
    if !safe_recording_id(&score.game_id, "game_")
        || score.game_type.is_empty()
        || score.game_type.len() > 80
        || score.variation_id.is_empty()
        || score.variation_id.len() > 80
        || score.score < 0
        || score.completed_at.len() > 40
        || !score.completed_at.ends_with('Z')
        || !matches!(score.platform.as_str(), "terminal" | "overlay")
    {
        return Err("Completed-game score is invalid.".to_string());
    }
    let directory = path
        .parent()
        .ok_or_else(|| "Score log path is invalid.".to_string())?;
    std::fs::create_dir_all(directory)
        .map_err(|error| format!("Could not create the score log: {error}"))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(directory, std::fs::Permissions::from_mode(0o700))
            .map_err(|error| format!("Could not secure the score log: {error}"))?;
    }

    let contents = match std::fs::read_to_string(path) {
        Ok(contents) => contents,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => String::new(),
        Err(error) => return Err(format!("Could not read the score log: {error}")),
    };
    let entries = contents
        .lines()
        .filter_map(|line| serde_json::from_str::<LocalScoreEntry>(line).ok())
        .collect::<Vec<_>>();
    if let Some(existing) = entries
        .iter()
        .find(|entry| entry.score.game_id == score.game_id)
    {
        if existing.score != score {
            return Err(format!(
                "Score {} conflicts with its local record.",
                score.game_id
            ));
        }
        return Ok(existing.clone());
    }

    // ponytail: scan JSONL on append; add an index only if real score histories make this slow.
    let previous_best = entries
        .iter()
        .filter(|entry| entry.score.game_type == score.game_type)
        .map(|entry| entry.score.score)
        .max();
    let high_score_updated = previous_best.map_or(true, |best| score.score > best);
