  type: T,
  data: AnalyticsEventDataMap[T],
  options: { id?: string; source?: string; subject?: string; time?: Date } = {},
): AnalyticsCloudEvent<T> {
  return {
    specversion: "1.0",
    id: options.id ?? createEventId(),
    source: options.source ?? "/tui-gamepigeon/client",
