  overlay.querySelector<HTMLButtonElement>("[data-restart]")?.focus();
}

/**
 * The canvas dispatches these from inside a Phaser input handler, and both menu
 * and restart tear the scene down — emitter included, mid-dispatch — so the
 * shell's answer waits for the next task.
 */
function handleSceneUi(action: "menu" | "restart" | "help"): void {
  window.setTimeout(() => {
    if (action === "menu") leaveToMenu();
    else if (action === "restart") restartRun();
    else openDialog("how-to-play");
