// ── Run lifecycle ────────────────────────────────────────────────────
//
// One run is on the floor at a time. Every launch goes through launchRun(), and
// every way a run stops goes through finishRun() (it ended on its own terms) or
// endRun() (something took it off the floor). Keeping those two apart is what
// keeps the promises in the README straight: only a finished shift submits a
// score and clears the save, and only a restart throws the save away.

/** Seeds stay inside the 32-bit range the engines index with. */
const SEED_LIMIT = 2 ** 31;

/**
 * A seed for a new run. `replacing` is the seed a restart is throwing away:
 * restart means "a different night", never "deal that one again", so the single
 * seed it must not return is that one.
 */
function randomSeed(replacing?: number): number {
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const seed = Math.floor(Math.random() * SEED_LIMIT);
    if (seed !== replacing) return seed;
  }
  // Eight collisions against one excluded value never happens in practice; the
  // fallback is here so the function cannot fail to return a usable seed.
  return ((replacing ?? 0) + 1) % SEED_LIMIT;
}

/** Actions the house takes on its own, rather than ones the player chose. */
function isEnvironmentAction(action: string): boolean {
  return action === "tick" || action === "bot_move";
}

function clearTickTimer(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
}

/**
 * Arms whatever advances the clock — and only ever one of them. With a live
 * crew the orchestrator owns the cadence, because it steps `tick` itself at the
 * end of each decision round; without one the shell is the clock. Either way
 * the engine's own `tickMs()` decides whether the clock should be running at
 * all: it returns 0 for every idle state (before the doors open, while a
 * decision card waits on the manager, after the shift ends), so this is
 * re-entered on every repaint rather than latched at launch.
 */
function scheduleRun(): void {
  clearTickTimer();
  if (!game || gameEnded || replaying) return;
  const interval = runPause.isPaused() ? 0 : game.tickMs();
  if (workerOrchestrator) {
    if (interval > 0) workerOrchestrator.start();
    else workerOrchestrator.pause();
    return;
  }
  if (interval <= 0) return;
  tickTimer = window.setTimeout(() => {
    tickTimer = undefined;
    if (!game || gameEnded || runPause.isPaused()) return;
    // Through performAction so the beat is journalled, saved and drawn like any
    // other action; drawGame() arms the next one.
    performAction("tick");
  }, interval);
}

/** Stops the clock for `reason`. The run keeps its place on the floor. */
function holdRun(reason: PauseReason): void {
  runPause.hold(reason);
  clearTickTimer();
  workerOrchestrator?.pause();
}

/** Drops one hold. The run only moves again once nothing else is holding it. */
function releaseRun(reason: PauseReason): void {
  if (!runPause.release(reason)) return;
  scheduleRun();
}

/**
 * Journals the run so the next launch can rebuild it: the seed, plus the
 * accepted actions in order (`overlay/persistence.ts`).
 *
 * Only actions the shell applied reach `runActions`, so a shift a live crew is
 * driving cannot be described this way — the orchestrator applies worker turns
 * straight to the engine. Rather than keep a record that would resume a
 * *different* night under this one's name, such a run keeps no record at all.
 */
function persistRun(): void {
  if (!game || !entry || replaying || gameEnded) return;
  if (workerOrchestrator) {
    clearSavedGame();
    savedGame = undefined;
    return;
  }
  const variation = entry.variations[variationCursor];
  if (!variation) return;
  const save: SavedGame = {
    schemaVersion: 1,
    ownerId: signedInUser()?.id ?? "",
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: variation.id,
    seed: runSeed,
    actions: [...runActions],
  };
  savedGame = saveGame(save) ? save : undefined;
}

interface LaunchOptions {
  /** Reuse a stored seed instead of dealing a new night. */
  seed?: number;
  /** A run already rebuilt from the save record. */
  restored?: { game: PlayableGame; actions: string[] };
}

/** Puts a run on the floor and shows it. The one way a game starts. */
function launchRun(selected: GameEntry, variationIndex: number, options: LaunchOptions = {}): void {
  const variation = selected.variations[variationIndex];
  if (!selected.create || !variation) return;
  // Whatever was on the floor is left behind, not completed.
  endRun("user_quit");
  entry = selected;
  cursor = MENU_GAMES.indexOf(selected);
  variationCursor = variationIndex;
  runSeed = options.seed ?? randomSeed();
  const restored = options.restored;
  game = restored?.game ?? selected.create(variation.id);
  if (!restored) game.reset(runSeed);
  runActions = restored ? [...restored.actions] : [];
  actionsTaken = runActions.length;
  gameStartedAt = Date.now();
  gameEnded = false;
  replaying = false;
  workerActivity.length = 0;
  activeTrace = createOverlayTrace(selected, variation.id, runSeed);
  gameSessionId = activeTrace.gameId;
  sessionReceiptId = gameSessionId;
  // A resumed run's actions were all applied by the shell under the same actor
  // rule performAction uses, so replaying that rule rebuilds the journal for
  // the part of the night that already happened instead of guessing at it.
  for (const action of runActions) {
    appendOverlayAction(activeTrace, action, isEnvironmentAction(action) ? "environment" : "human");
  }
  persistTrace(activeTrace);
  attachWorkerOrchestrator(game);
  screen = "game";
  captureOverlayEvent(
    "game.started",
    { game_type: selected.id, variation_id: variation.id },
    gameSessionId,
  );
  renderGameScreen();
  persistRun();
  scheduleRun();
}

/** `gamepigeon:launch` and `?game=` both name a game and variation by id. */
function launchById(gameId: string, variationId?: string | null): boolean {
  const selected = MENU_GAMES.find(({ id }) => id === gameId);
  if (!selected || !isPlayable(selected)) return false;
  // An unknown or missing variation opens the first one: `classic` is the
  // host's default for games that have no modes of their own.
  const index = selected.variations.findIndex(({ id }) => id === variationId);
  launchRun(selected, index < 0 ? 0 : index);
  return true;
}

/**
 * Rebuilds the saved run action-by-action and puts it back on the floor.
 * Returns false when the record cannot describe this build any anymore, having
 * dropped it: resuming a run that is not the one the record names would be
 * worse than starting from the menu.
 */
function resumeSavedGame(): boolean {
  const saved = savedGame;
  if (!saved) return false;
  const selected = MENU_GAMES.find(({ id }) => id === saved.gameId);
  const variationIndex = selected?.variations.findIndex(({ id }) => id === saved.variationId) ?? -1;
  const restored = selected ? restoreGame(selected, saved) : null;
  // A run that was already over when it was saved has nothing to go back to,
  // and finishing it again would submit a second score for the same night.
  if (!selected || variationIndex < 0 || !restored || restored.game.isOver()) {
    clearSavedGame();
    savedGame = undefined;
    return false;
  }
  launchRun(selected, variationIndex, { seed: saved.seed, restored });
  return true;
}

/**
 * Start over: a new run of the same game and variation, on a seed that is never
 * the one being replaced, with the old save thrown away (README).
 */
function restartRun(): void {
  if (!entry) return;
  const selected = entry;
  const variationIndex = variationCursor;
  const replaced = runSeed;
  closeDialog();
  endRun("restart");
  clearSavedGame();
  savedGame = undefined;
  launchRun(selected, variationIndex, { seed: randomSeed(replaced) });
}

/**
 * Ends the shift and goes back to the menu, leaving the save exactly as it is
 * (README): the seed and the action log still describe this run, so it can be
 * resumed from the menu or on the next launch.
 */
function leaveToMenu(): void {
  persistRun();
  endRun("user_quit");
  closeDialog();
  screen = "menu";
  cursor = entry ? MENU_GAMES.indexOf(entry) : -1;
  drawMenu();
}

/**
 * Takes the run off the floor without finishing it. `reason` seals its trace —
 * a shift that ended on its own terms was already sealed by finishRun, so this
 * only ever reports the runs that stopped for some other reason, and none of
 * them carry a score.
 */
function endRun(reason: EpisodeEndReason): void {
  clearTickTimer();
  cancelTraceFlush();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  runPause.clear();
  if (activeTrace && !gameEnded) submitTrace(activeTrace, reason);
  activeTrace = undefined;
  game = undefined;
  gameEnded = true;
}

/**
 * The shift ran to its own end. This is the only path that submits a score, so
 * it is also the only one that has to be safe to reach twice: every repaint
 * asks whether the run is over, and a completed run stays on screen.
 */
function finishRun(): void {
  if (!game || !entry || gameEnded) return;
  gameEnded = true;
  clearTickTimer();
  cancelTraceFlush();
  stopWorkerOrchestrator();

  const score = game.score();
  const won = game.hasWon();
  const variationId = entry.variations[variationCursor]?.id ?? "classic";
  const completedAt = new Date();
  // The night is over, so the save has nothing left to resume. Left behind it
  // would offer a finished shift as "Resume" and submit its score a second time.
  clearSavedGame();
  savedGame = undefined;
  if (activeTrace) {
    submitTrace(activeTrace, won ? "won" : "lost", score);
    activeTrace = undefined;
  }
  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: variationId,
    outcome: "completed",
    score,
    success: won,
    duration_ms: Math.max(0, completedAt.getTime() - gameStartedAt),
    actions_taken: actionsTaken,
  }, gameSessionId);
  void invoke("append_local_score", {
    score: {
      game_id: gameSessionId,
      game_type: entry.id,
      variation_id: variationId,
      score,
      success: won,
      completed_at: completedAt.toISOString(),
      duration_ms: Math.max(0, completedAt.getTime() - gameStartedAt),
      platform: "overlay",
    },
  }).then(() => refreshLocalScores()).catch(() => undefined);
  showGameEndOverlay(score, won);
}

/**
 * The end card, over the board it belongs to. The service report, the evidence
 * receipt and the timeline are all read off the finished game, which is why the
 * run stays loaded after finishRun() — and why the card is what offers the two
 * ways out rather than dropping the player back on the menu automatically.
 */
function showGameEndOverlay(score: number, won: boolean): void {
  if (!game || !entry) return;
  const board = screenElement.querySelector<HTMLElement>(".board");
  if (!board) return;
  board.querySelector(".game-end-overlay")?.remove();
  const isArena = game.name === "restaurant-arena";
  const best = personalBest(entry.id, score);
  const overlay = document.createElement("div");
  overlay.className = "game-end-overlay";
  overlay.dataset.tone = won ? "win" : "loss";
  overlay.innerHTML = `<div class="game-end-content${isArena ? " arena-end-content" : ""}">
    <h2 class="game-end-title">${won ? "Shift complete" : "Shift over"}</h2>
    <p class="game-end-stats">Score ${score}${best === undefined ? "" : ` · Personal best ${best}`}</p>
    ${getArenaDebriefHtml()}
    ${getArenaEvidenceHtml()}
    ${getArenaTimelineHtml()}
    ${sessionReceiptHtml()}
    <div class="game-end-actions">
      <button type="button" class="primary" data-restart><kbd>R</kbd> Play again</button>
      <button type="button" data-menu>‹ Menu</button>
      ${isArena ? `<div class="export-trace-group">
        <button type="button" class="export-trace-btn" data-action="export-trace">Export Trace</button>
        <button type="button" class="export-trace-btn-alt" data-action="export-trace-jsonl">JSONL</button>
      </div>` : ""}
    </div>
  </div>`;
  board.append(overlay);
  overlay.querySelector<HTMLButtonElement>("[data-restart]")?.focus();
}

/**
 * The canvas dispatches these from inside a Phaser input handler, and both menu
 * and restart tear the scene down — emitter included, mid-dispatch — so the
 * shell's answer waits for the next task.
 */
function handleSceneUi(action: "menu" | "restart" | "help"): void {
  window.setTimeout(() => {
    if (action === "menu") leaveToMenu();
    else if (action === "restart") restartRun();
    else openDialog("how-to-play");
  }, 0);
}

// ── Dialogs ──────────────────────────────────────────────────────────
//
// Three cards live in index.html rather than in #screen, because they sit over
// whatever the screen is showing: the pause card, How to Play, and the sign-out
// confirmation. Only one is ever up, and while any of them is up the run is
// held under the "dialog" hold — so closing How to Play can never resume a
// shift the agent paused.

const DIALOG_SELECTORS: Record<DialogId, string> = {
  pause: "#return-prompt",
  "how-to-play": "#how-to-play",
  signout: "#signout-prompt",
};

function dialogElement(id: DialogId): HTMLElement | null {
  return document.querySelector<HTMLElement>(DIALOG_SELECTORS[id]);
}

/** How to Play opened off the pause card goes back to it, not to the floor. */
let howToPlayReturnsToPause = false;

/**
 * The pause card describes the run behind it, so it is written on every open.
 * The agent can stop the player on the same beat a shift ends, and then there
 * is nothing to continue — see pausePrompt().
 */
function renderPauseCard(): void {
  const prompt = dialogElement("pause");
  if (!prompt) return;
  const running = screen === "game" && game ? { over: game.isOver(), won: game.hasWon() } : null;
  const state = pausePrompt(running);
  const title = prompt.querySelector<HTMLElement>("#return-title");
  if (title) setText(title, state.title);
  if (state.tone) prompt.dataset.tone = state.tone;
  else delete prompt.dataset.tone;
  const proceed = prompt.querySelector<HTMLButtonElement>("#continue-game");
  if (proceed) proceed.hidden = !state.canContinue;
}

function openDialog(id: DialogId): void {
  const element = dialogElement(id);
  if (!element || openDialogId === id) return;
  if (openDialogId) {
    const previous = dialogElement(openDialogId);
    if (previous) previous.hidden = true;
  }
  openDialogId = id;
  if (id === "pause") renderPauseCard();
  element.hidden = false;
  holdRun("dialog");
  element.querySelector<HTMLButtonElement>("button")?.focus();
}

function closeDialog(): void {
  if (!openDialogId) return;
  const element = dialogElement(openDialogId);
  if (element) element.hidden = true;
  openDialogId = undefined;
  howToPlayReturnsToPause = false;
  releaseRun("dialog");
}

function closeHowToPlay(): void {
  if (howToPlayReturnsToPause) {
    howToPlayReturnsToPause = false;
    const guide = dialogElement("how-to-play");
    if (guide) guide.hidden = true;
    openDialogId = undefined;
    openDialog("pause");
    return;
  }
  closeDialog();
}

/**
 * Hand the window back to the terminal. The agent's hold stays on, because a
 * shift must not tick on behind a window nobody can see; `gamepigeon:resume`
 * is what lifts it when the agent shows the overlay again.
 */
function backToCoding(): void {
  holdRun("agent");
  closeDialog();
  void Promise.resolve(windowHandle.hide()).catch(() => undefined);
}

/** Back to the shift: the agent is done, and the card is the last hold. */
function resumeFromPause(): void {
  releaseRun("agent");
  closeDialog();
}

/**
 * Signing out abandons the shift on the floor and drops its save: the record
 * belongs to the account that is leaving, and the next person to open Tui on
 * this machine must not be handed it.
 */
async function confirmSignOut(): Promise<void> {
  try {
    await signOut();
  } catch {
    // signOut() throws with the session intact, so nothing may act as though
    // the account is gone — the card says so and stays up.
    const title = document.querySelector<HTMLElement>("#signout-title");
    if (title) setText(title, "Could not sign out. Try again.");
    return;
  }
  persistRun();
  endRun("user_quit");
  clearSavedGame();
  savedGame = undefined;
  clearSignInPending();
  closeDialog();
  entry = undefined;
  cursor = -1;
  localScores = { personal_bests: [], recent: [], top_scores: [] };
  drawGate();
}

/** Wire the shell's three cards once; their content is written on open. */
function bindDialogs(): void {
  document.querySelector<HTMLButtonElement>("#return-code")?.addEventListener("click", backToCoding);
  document.querySelector<HTMLButtonElement>("#continue-game")?.addEventListener("click", resumeFromPause);
  document.querySelector<HTMLButtonElement>("#how-to-play-from-pause")?.addEventListener("click", () => {
    howToPlayReturnsToPause = true;
    openDialog("how-to-play");
  });
  document.querySelector<HTMLButtonElement>("#return-menu")?.addEventListener("click", leaveToMenu);
  document.querySelector<HTMLButtonElement>("#how-to-play-close")?.addEventListener("click", closeHowToPlay);
  document.querySelector<HTMLButtonElement>("#signout-confirm")?.addEventListener("click", () => {
    void confirmSignOut();
  });
  document.querySelector<HTMLButtonElement>("#signout-cancel")?.addEventListener("click", closeDialog);
}

/** A card up owns the keyboard; the screen behind it never sees these keys. */
function handleDialogKey(event: KeyboardEvent): void {
  if (!openDialogId) return;
  if (event.key === "Escape") {
    event.preventDefault();
    if (openDialogId === "pause") backToCoding();
    else if (openDialogId === "how-to-play") closeHowToPlay();
    else closeDialog();
    return;
  }
  if (event.key === "Enter") {
    event.preventDefault();
    if (openDialogId === "signout") void confirmSignOut();
    else if (openDialogId === "how-to-play") closeHowToPlay();
    // The pause card's own <kbd> hint: Enter is the way back to the prompt.
    else backToCoding();
    return;
  }
  if (openDialogId === "pause" && event.key.toLowerCase() === "m") {
    event.preventDefault();
    leaveToMenu();
  }
}

