// ── Host events ──────────────────────────────────────────────────────
//
// The native shell talks to the webview by dispatching these on `window`
// (dispatch_overlay_event / apply_action in tauri/src/main.rs). They are the
// agent's side of the session: the harness hooks show the overlay on a prompt,
// pause it when the agent needs the player, and snap it back to the menu when a
// new session starts.

window.addEventListener("gamepigeon:launch", (event) => {
  const detail = (event as CustomEvent<{ game?: string; variation?: string }>).detail;
  if (!detail?.game || screen === "gate") return;
  launchById(detail.game, detail.variation);
});

window.addEventListener("gamepigeon:pause", () => {
  if (!settings.autoPauseOnStop) return;
  holdRun("agent");
  // The card is also what tells the player why the window came forward and how
  // to get back to their prompt, so it is shown off the menu too.
  if (!minimized) openDialog("pause");
});

window.addEventListener("gamepigeon:resume", () => {
  if (openDialogId === "pause") closeDialog();
  releaseRun("agent");
  restoreFromPill();
});

window.addEventListener("gamepigeon:reset", () => {
  // A new session starts from the menu. The save is left exactly as it was, so
  // the interrupted shift is still there to resume (README).
  if (!settings.resetOnNewSession || screen === "gate") return;
  leaveToMenu();
});

window.addEventListener("gamepigeon:auth-success", () => {
  clearSignInPending();
  // The event carries only the email; the session file has the account id the
  // save record and the analytics subject are keyed by.
  void loadAuthSession().then((user) => {
    if (!user) {
      setSignInStatus("error", "Sign-in did not complete. Try again.");
      return;
    }
    adoptSavedGame(user.id);
    unlockTui(user);
    void invoke<string | null>("read_sync_error").then(setSyncError).catch(() => undefined);
    refreshLocalScores();
    recoverTraces();
  });
});

window.addEventListener("gamepigeon:auth-error", (event) => {
  clearSignInPending();
  const detail = (event as CustomEvent<unknown>).detail;
  setSignInStatus("error", typeof detail === "string" && detail ? detail : "Could not sign in. Try again.");
});

window.addEventListener("gamepigeon:sync-error", (event) => {
  const detail = (event as CustomEvent<unknown>).detail;
  setSyncError(typeof detail === "string" && detail ? detail : "Sync paused.");
});

window.addEventListener("gamepigeon:sync-success", () => setSyncError(null));

bindWindowChrome();
bindDialogs();
bindUpdateBanner();
void refreshUpdateBanner();

