/** Called once a session exists: leave the gate and show the arcade. */
function unlockTui(user: AuthUser): void {
  setSignedInUser(user);
  openInitialScreen();
  renderAccountChip();
  renderSignInBar();
}

/**
 * Takes ownership of the stored save, if it is this account's. A record left by
 * someone else on the same machine is left alone rather than deleted — it is
 * still their run, and they will be handed it again when they sign back in.
 */
function adoptSavedGame(ownerId: string): void {
  const saved = loadSavedGame();
  savedGame = saved?.ownerId === ownerId ? saved : undefined;
}

/**
 * Where a launch lands. A deep link (`?game=`, or `--game` through the host)
 * names the run to open; otherwise the menu, unless the player has asked to be
 * put straight back into the last one.
 */
function openInitialScreen(): void {
  const params = new URLSearchParams(window.location.search);
  const requested = params.get("game");
  if (requested && launchById(requested, params.get("variation"))) return;
  if (settings.resumeLastGame && resumeSavedGame()) return;
  screen = "menu";
  cursor = -1;
  drawMenu();
}

