 * Arms whatever advances the clock — and only ever one of them. With a live
 * crew the orchestrator owns the cadence, because it steps `tick` itself at the
 * end of each decision round; without one the shell is the clock. Either way
 * the engine's own `tickMs()` decides whether the clock should be running at
 * all: it returns 0 for every idle state (before the doors open, while a
 * decision card waits on the manager, after the shift ends), so this is
 * re-entered on every repaint rather than latched at launch.
 */
function scheduleRun(): void {
  clearTickTimer();
  if (!game || gameEnded || replaying) return;
  const interval = runPause.isPaused() ? 0 : game.tickMs();
  if (workerOrchestrator) {
    if (interval > 0) workerOrchestrator.start();
    else workerOrchestrator.pause();
    return;
  }
  if (interval <= 0) return;

