import { describe, expect, test } from "bun:test";
import { PauseGate, pausePrompt } from "./pause-state.js";

describe("pause holds", () => {
  test("reports which hold actually stopped and restarted the run", () => {
    const gate = new PauseGate();
    expect(gate.hold("agent")).toBe(true);
