import { describe, expect, test } from "bun:test";
import { clearSavedGame, loadSavedGame, restoreGame, saveGame, type SavedGame } from "./persistence.js";
import { MENU_GAMES } from "../src/games/registry.js";

const STORAGE_KEY = "gamepigeon.arcade.active-game.v1";

/** A `Storage` the tests own, so no case can see another's record. */
function fakeStorage(options: { failWrites?: boolean } = {}): Storage {
  const entries = new Map<string, string>();
  return {
    get length() {
      return entries.size;
    },
    key: (index: number) => [...entries.keys()][index] ?? null,
    getItem: (key: string) => entries.get(key) ?? null,
    setItem: (key: string, value: string) => {
      if (options.failWrites) throw new Error("QuotaExceededError");
      entries.set(key, value);
    },
    removeItem: (key: string) => {
      entries.delete(key);
    },
    clear: () => entries.clear(),
  } as Storage;
}

const arena = MENU_GAMES.find((entry) => entry.id === "restaurant-arena")!;

function save(overrides: Partial<SavedGame> = {}): SavedGame {
  return {
    schemaVersion: 1,
    ownerId: "usr_test",
    gameId: arena.id,
    gameVersion: arena.version,
    variationId: arena.variations[0]!.id,
    seed: 4242,
    actions: ["sim_start", "tick", "tick"],
    ...overrides,
  };
}

describe("the one save record", () => {
  test("round-trips the run through storage", () => {
    const storage = fakeStorage();
    expect(saveGame(save(), storage)).toBe(true);
    expect(loadSavedGame(storage)).toEqual(save());
  });

  test("overwrites rather than accumulating records", () => {
    const storage = fakeStorage();
    saveGame(save(), storage);
    saveGame(save({ seed: 99, actions: ["tick"] }), storage);
    expect(storage.length).toBe(1);
    expect(loadSavedGame(storage)?.seed).toBe(99);
  });

  test("a storage that refuses the write reports it without throwing", () => {
    // A localStorage over quota must not take a shift down with it.
    expect(saveGame(save(), fakeStorage({ failWrites: true }))).toBe(false);
  });

  test("clearing leaves nothing behind for the next launch", () => {
    const storage = fakeStorage();
    saveGame(save(), storage);
    clearSavedGame(storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("drops a record it cannot rebuild instead of keeping a stale one", () => {
    // Past MAX_ACTIONS the record can no longer describe the run, and a
    // truncated prefix would rebuild a *different* one.
    const storage = fakeStorage();
    saveGame(save(), storage);
    expect(saveGame(save({ actions: Array.from({ length: 50_001 }, () => "tick") }), storage)).toBe(false);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("reads nothing out of a corrupt or foreign record", () => {
    const storage = fakeStorage();
    storage.setItem(STORAGE_KEY, "{not json");
    expect(loadSavedGame(storage)).toBeNull();
    storage.setItem(STORAGE_KEY, JSON.stringify({ ...save(), seed: 1.5 }));
    expect(loadSavedGame(storage)).toBeNull();
  });
});

describe("rebuilding a saved run", () => {
  test("replays the actions onto the stored seed", () => {
    const restored = restoreGame(arena, save());
    expect(restored?.actions).toEqual(["sim_start", "tick", "tick"]);
    // Two ticks past the doors opening: the rebuild is the run, not a new one.
    expect((restored?.game.state() as { episode: { tick: number } }).episode.tick).toBe(2);
  });

  test("refuses a record from another game or another ruleset version", () => {
    expect(restoreGame(arena, save({ gameId: "checkers" }))).toBeNull();
    expect(restoreGame(arena, save({ gameVersion: "0" }))).toBeNull();
  });

  test("refuses an action this build no longer accepts", () => {
    // Rebuilding around a dropped action would silently produce a different run.
    expect(restoreGame(arena, save({ actions: ["sim_start", "serve_by_hand"] }))).toBeNull();
  });
});

