import { describe, expect, test } from "bun:test";
import {
  applyOverlayWindowSize,
  COMPACT_SIZE,
  EXPANDED_SIZE,
  MIN_SIZE,
  PILL_SIZE,
  overlayWindowSize,
  type OverlaySize,
  type OverlayWindow,
} from "./tauri-bridge.js";

/** Records what the window was actually told to do, and in what order. */
function fakeWindow(): { window: OverlayWindow; calls: string[] } {
  const calls: string[] = [];
  const record = (label: string) => (size: unknown) => {
    const { width, height } = size as OverlaySize;
    calls.push(`${label} ${width}x${height}`);
    return Promise.resolve();
  };
  return {
    calls,
    window: {
      hide: async () => undefined,
      center: async () => undefined,
      startDragging: async () => undefined,
      setSize: record("size"),
      setMinSize: record("min"),
    } as unknown as OverlayWindow,
  };
}

describe("overlay frame sizes", () => {
  test("are the sizes the README and the preview are written against", () => {
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("carry a minimum the mode can actually fit in", () => {
    expect(overlayWindowSize("compact")).toEqual({ size: COMPACT_SIZE, minSize: MIN_SIZE });
    expect(overlayWindowSize("expanded")).toEqual({ size: EXPANDED_SIZE, minSize: MIN_SIZE });
    // The pill sits far below the arcade's floor, so it is its own minimum.
    expect(overlayWindowSize("pill")).toEqual({ size: PILL_SIZE, minSize: PILL_SIZE });
  });
});

describe("applying a frame", () => {
  test("lowers the minimum before shrinking to the pill", async () => {
    // Setting the size first leaves a 500x700 "pill": the window cannot go
    // below a minimum that is still the arcade's.
    const { window, calls } = fakeWindow();
    await applyOverlayWindowSize(window, "pill");
    expect(calls).toEqual(["min 144x48", "size 144x48"]);
  });

  test("raises the minimum again on the way back out", async () => {
    // Without this the next drag could squash the board back to pill height.
    const { window, calls } = fakeWindow();
    await applyOverlayWindowSize(window, "compact");
    expect(calls).toEqual(["min 500x700", "size 600x850"]);
  });

  test("expands to the wider frame on the same floor", async () => {
    const { window, calls } = fakeWindow();
    await applyOverlayWindowSize(window, "expanded");
    expect(calls).toEqual(["min 500x700", "size 830x900"]);
  });
});

