1201:function randomSeed(replacing?: number): number {
1202:  for (let attempt = 0; attempt < 8; attempt += 1) {
1203:    const seed = Math.floor(Math.random() * SEED_LIMIT);
1204:    if (seed !== replacing) return seed;
1205:  }
1206:  // Eight collisions against one excluded value never happens in practice; the
1207:  // fallback is here so the function cannot fail to return a usable seed.
1208:  return ((replacing ?? 0) + 1) % SEED_LIMIT;
1209:}
1210:
1211:/** Actions the house takes on its own, rather than ones the player chose. */
1212:function isEnvironmentAction(action: string): boolean {
1213:  return action === "tick" || action === "bot_move";
1214:}
1215:
1216:function clearTickTimer(): void {
1217:  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
1218:  tickTimer = undefined;
1219:}
1220:
1221:/**
1222: * Arms whatever advances the clock — and only ever one of them. With a live
1223: * crew the orchestrator owns the cadence, because it steps `tick` itself at the
1224: * end of each decision round; without one the shell is the clock. Either way
1225: * the engine's own `tickMs()` decides whether the clock should be running at
1226: * all: it returns 0 for every idle state (before the doors open, while a
1227: * decision card waits on the manager, after the shift ends), so this is
1228: * re-entered on every repaint rather than latched at launch.
1229: */
1230:function scheduleRun(): void {
1231:  clearTickTimer();
1232:  if (!game || gameEnded || replaying) return;
1233:  // A game with no `tickMs` never advances on its own; it waits for the player.
1234:  const interval = runPause.isPaused() ? 0 : game.tickMs?.() ?? 0;
1235:  if (workerOrchestrator) {
1236:    if (interval > 0) workerOrchestrator.start();
1237:    else workerOrchestrator.pause();
1238:    return;
1239:  }
1240:  if (interval <= 0) return;
1241:  tickTimer = window.setTimeout(() => {
1242:    tickTimer = undefined;
1243:    if (!game || gameEnded || runPause.isPaused()) return;
1244:    // Through performAction so the beat is journalled, saved and drawn like any
1245:    // other action; drawGame() arms the next one.
1246:    performAction("tick");
1247:  }, interval);
1248:}
1249:
1250:/** Stops the clock for `reason`. The run keeps its place on the floor. */
1251:function holdRun(reason: PauseReason): void {
1252:  runPause.hold(reason);
1253:  clearTickTimer();
1254:  workerOrchestrator?.pause();
1255:}
1256:
1257:/** Drops one hold. The run only moves again once nothing else is holding it. */
1258:function releaseRun(reason: PauseReason): void {
1259:  if (!runPause.release(reason)) return;
1260:  scheduleRun();
1261:}
1262:
1263:/**
1264: * Journals the run so the next launch can rebuild it: the seed, plus the
1265: * accepted actions in order (`overlay/persistence.ts`).
1266: *
1267: * Only actions the shell applied reach `runActions`, so a shift a live crew is
1268: * driving cannot be described this way — the orchestrator applies worker turns
1269: * straight to the engine. Rather than keep a record that would resume a
1270: * *different* night under this one's name, such a run keeps no record at all.
1271: */
1272:function persistRun(): void {
1273:  if (!game || !entry || replaying || gameEnded) return;
1274:  if (workerOrchestrator) {
1275:    clearSavedGame();
1276:    savedGame = undefined;
