1300:/** Puts a run on the floor and shows it. The one way a game starts. */
1301:function launchRun(selected: GameEntry, variationIndex: number, options: LaunchOptions = {}): void {
1302:  const variation = selected.variations[variationIndex];
1303:  if (!selected.create || !variation) return;
1304:  // Whatever was on the floor is left behind, not completed.
1305:  endRun("user_quit");
1306:  entry = selected;
1307:  cursor = MENU_GAMES.indexOf(selected);
1308:  variationCursor = variationIndex;
1309:  runSeed = options.seed ?? randomSeed();
1310:  const restored = options.restored;
1311:  game = restored?.game ?? selected.create(variation.id);
1312:  if (!restored) game.reset(runSeed);
1313:  runActions = restored ? [...restored.actions] : [];
1314:  actionsTaken = runActions.length;
1315:  gameStartedAt = Date.now();
1316:  gameEnded = false;
1317:  replaying = false;
1318:  workerActivity.length = 0;
1319:  activeTrace = createOverlayTrace(selected, variation.id, runSeed);
1320:  gameSessionId = activeTrace.gameId;
1321:  sessionReceiptId = gameSessionId;
1322:  // A resumed run's actions were all applied by the shell under the same actor
1323:  // rule performAction uses, so replaying that rule rebuilds the journal for
1324:  // the part of the night that already happened instead of guessing at it.
1325:  for (const action of runActions) {
1326:    appendOverlayAction(activeTrace, action, isEnvironmentAction(action) ? "environment" : "human");
1327:  }
1328:  persistTrace(activeTrace);
1329:  attachWorkerOrchestrator(game);
1330:  screen = "game";
1331:  captureOverlayEvent(
1332:    "game.started",
1333:    { game_type: selected.id, variation_id: variation.id },
1334:    gameSessionId,
1335:  );
1336:  renderGameScreen();
1337:  persistRun();
1338:  scheduleRun();
1339:}
