1341:/** `gamepigeon:launch` and `?game=` both name a game and variation by id. */
1342:function launchById(gameId: string, variationId?: string | null): boolean {
1343:  const selected = MENU_GAMES.find(({ id }) => id === gameId);
1344:  if (!selected || !isPlayable(selected)) return false;
1345:  // An unknown or missing variation opens the first one: `classic` is the
1346:  // host's default for games that have no modes of their own.
1347:  const index = selected.variations.findIndex(({ id }) => id === variationId);
1348:  launchRun(selected, index < 0 ? 0 : index);
1349:  return true;
1350:}
1351:
1352:/**
1353: * Rebuilds the saved run action-by-action and puts it back on the floor.
1354: * Returns false when the record can no longer describe this build, having
1355: * dropped it: resuming a run that is not the one the record names would be
1356: * worse than starting from the menu.
1357: */
1358:function resumeSavedGame(): boolean {
1359:  const saved = savedGame;
1360:  if (!saved) return false;
1361:  const selected = MENU_GAMES.find(({ id }) => id === saved.gameId);
1362:  const variationIndex = selected?.variations.findIndex(({ id }) => id === saved.variationId) ?? -1;
1363:  const restored = selected ? restoreGame(selected, saved) : null;
1364:  // A run that was already over when it was saved has nothing to go back to,
1365:  // and finishing it again would submit a second score for the same night.
1366:  if (!selected || variationIndex < 0 || !restored || restored.game.isOver()) {
1367:    clearSavedGame();
1368:    savedGame = undefined;
1369:    return false;
1370:  }
1371:  launchRun(selected, variationIndex, { seed: saved.seed, restored });
1372:  return true;
1373:}
1374:
1375:/**
1376: * Start over: a new run of the same game and variation, on a seed that is never
1377: * the one being replaced, with the old save thrown away (README).
1378: */
1379:function restartRun(): void {
1380:  if (!entry) return;
1381:  const selected = entry;
1382:  const variationIndex = variationCursor;
1383:  const replaced = runSeed;
1384:  closeDialog();
1385:  endRun("restart");
1386:  clearSavedGame();
1387:  savedGame = undefined;
1388:  launchRun(selected, variationIndex, { seed: randomSeed(replaced) });
1389:}
1390:
1391:/**
1392: * Ends the shift and goes back to the menu, leaving the save exactly as it is
1393: * (README): the seed and the action log still describe this run, so it can be
1394: * resumed from the menu or on the next launch.
1395: */
1396:function leaveToMenu(): void {
1397:  persistRun();
1398:  endRun("user_quit");
1399:  closeDialog();
1400:  screen = "menu";
1401:  cursor = entry ? MENU_GAMES.indexOf(entry) : -1;
1402:  drawMenu();
1403:}
