.arena-stage > [data-phaser-mount] canvas { display: block; }

      .arena-worker-mode {
        position: absolute;
        left: 10px;
        bottom: 10px;
        z-index: 40;
        margin: 0;
        padding: 6px 9px;

      /* Player intervention panel — the one DOM control over the canvas
         floor, needed only because free text can't be typed into Phaser. */
      .arena-intervene-toggle {
        position: absolute;
        right: 10px;
        bottom: 10px;
        z-index: 40;
        padding: 7px 12px;
        border: 1px solid #6b5a44;
        border-radius: 999px;
        background: #2f241a;
        color: #fff3d6;
        font: 750 11px/1 var(--mono);
        cursor: pointer;
        box-shadow: 0 6px 16px rgba(0, 0, 0, .3);
      }
      .arena-intervene-toggle:hover, .arena-intervene-toggle:focus-visible { background: #4a3a2c; outline: none; }
      .arena-intervene-toggle[aria-expanded="true"] { background: #f2cc5c; color: #2b2118; border-color: #f2cc5c; }
      .arena-intervene-panel {
        position: absolute;
        right: 10px;
        bottom: 48px;
        z-index: 41;
        width: min(280px, calc(100% - 20px));
        max-height: min(420px, calc(100% - 60px));
        overflow-y: auto;
        display: grid;
        gap: 6px;

